#pragma once

#include <QImage>
#include <QString>
#include <QStringList>
#include <vector>

// Brush tips and textures, all generated by this code from fixed seeds. There are no bundled
// image files and nothing derived from another application's assets (see ARCHITECTURE.md,
// "Brush tips and textures: provenance").
//
// Images are QImage::Format_Grayscale8; 255 means full paint. Tips are square, centred, with the
// travel direction along +x (a tip that follows the stroke direction is rotated to it). Textures
// tile seamlessly. Generated once on first use; safe to call from any thread afterwards.
namespace BrushTips {

struct Tip
{
    QString id;
    QString label;
    std::vector<QImage> mips; // level 0 is the largest; each next level is half the size
    // How much paint one pass of the tip lays along its densest line in the travel direction, as
    // a fraction of the tip width (1 for a hard round tip). Used to normalise flow.
    double passLength = 1.0;
};

// passLength for the computed round tip with this hardness.
double roundPassLength(double hardness);

struct Texture
{
    QString id;
    QString label;
    QImage image;
};

// nullptr for an unknown id.
const Tip *tip(const QString &id);
const Texture *texture(const QString &id);
QStringList tipIds();
QStringList textureIds();

// Deterministic hash in [0, 1) of three integers (also used for per-stroke jitter and dither).
double hash01(qint64 a, qint64 b, quint64 salt);

} // namespace BrushTips
